--liquibase formatted sql
--changeset framework:sample_data runOnChange:true runInTransaction:true splitStatements:false logicalFilePath:data/cumulative_changelog.xml
-- Sample / demo tables for local UI exploration.

-- Remove the previous sample location (the first configured application schema)
-- before creating the canonical postgresto demo table.
DROP TABLE IF EXISTS ${appschema}.demo;
DROP TABLE IF EXISTS ${appschema}.demo_history;

CREATE TABLE postgresto.demo (
  id text PRIMARY KEY,
  parent text REFERENCES postgresto.demo (id),
  jsondata jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- Main PostgreSQL types as columns (names match types)
  text text,
  varchar varchar(64),
  char char(1),
  smallint smallint,
  integer integer,
  bigint bigint,
  numeric numeric(14, 4),
  real real,
  double_precision double precision,
  boolean boolean,
  date date,
  time time,
  timestamp timestamp without time zone,
  timestamptz timestamptz,
  interval interval,
  uuid uuid,
  json json,
  jsonb jsonb,
  money money,
  bytea bytea,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);

-- History snapshots for postgresto.demo (written by postgresto.history_log_changes).
CREATE TABLE postgresto.demo_history (
  id text PRIMARY KEY,
  jsondata jsonb NOT NULL DEFAULT '{}'::jsonb
);

-- Attach history logging before seed INSERT so CREATE snapshots are recorded.
DROP TRIGGER IF EXISTS demo_trg_log_history ON postgresto.demo;
CREATE TRIGGER demo_trg_log_history
  AFTER INSERT OR UPDATE OR DELETE ON postgresto.demo
  FOR EACH ROW
  EXECUTE FUNCTION postgresto.history_log_changes();



-- 100 sample rows in a 5-level parent→id tree + typed PG columns / jsondata
-- L1: 1–2 · L2: 3–6 · L3: 7–14 · L4: 15–30 · L5: 31–100
SELECT
  'DEMO-' || lpad(i::text, 3, '0'),
  CASE
    WHEN i <= 2 THEN NULL
    WHEN i <= 6 THEN 'DEMO-' || lpad((1 + ((i - 3) / 2))::text, 3, '0')
    WHEN i <= 14 THEN 'DEMO-' || lpad((3 + ((i - 7) / 2))::text, 3, '0')
    WHEN i <= 30 THEN 'DEMO-' || lpad((7 + ((i - 15) / 2))::text, 3, '0')
    ELSE 'DEMO-' || lpad((15 + ((i - 31) % 16))::text, 3, '0')
  END,
  jsonb_build_object(
    'text', 'L' || lvl || ' Sample ' || i,
    'number', (i * 1.5)::numeric,
    'boolean', (i % 2 = 1),
    'date', to_char(date '2020-01-01' + ((i - 1) || ' days')::interval, 'YYYY-MM-DD'),
    -- Varied string formats for sort/display: Z / offsets / naive / ms / space-T.
    -- Absolute instants advance with i (UTC base); contrast with timestamptz column offsets.
    'datetime', dt.json_datetime,
    'level', lvl,
    'json', jsonb_build_object(
      'n', i,
      'label', 'json-' || i,
      'tags', CASE
        WHEN i % 2 = 0 THEN jsonb_build_array('even', 'demo')
        ELSE jsonb_build_array('odd')
      END
    )
  ),
  'L' || lvl || ' Sample ' || i,
  'C-' || lpad(i::text, 3, '0'),
  chr(65 + ((i - 1) % 26)),
  ((i % 200) - 100)::smallint,
  i * 10,
  (i::bigint * 1000000007),
  (i * 12.3456)::numeric(14, 4),
  (i * 1.25)::real,
  (i * pi())::double precision,
  (i % 2 = 1),
  date '2020-01-01' + ((i - 1) || ' days')::interval,
  time '08:00' + ((i % 24) || ' hours')::interval + ((i % 60) || ' minutes')::interval,
  dt.col_timestamp,
  dt.col_timestamptz,
  make_interval(days => i % 30, hours => i % 24, mins => i % 60),
  (
    substr(md5(i::text), 1, 8) || '-' ||
    substr(md5(i::text), 9, 4) || '-' ||
    '4' || substr(md5(i::text), 14, 3) || '-' ||
    'a' || substr(md5(i::text), 18, 3) || '-' ||
    substr(md5(i::text), 21, 12)
  )::uuid,
  json_build_object('n', i, 'label', 'json-' || i),
  jsonb_build_object(
    'n', i,
    'region', CASE WHEN i % 3 = 0 THEN 'EU' WHEN i % 3 = 1 THEN 'US' ELSE 'APAC' END,
    'flags', CASE WHEN i % 2 = 0 THEN jsonb_build_array('even') ELSE jsonb_build_array('odd', 'demo') END
  ),
  ((i * 1.25)::numeric(12, 2))::money,
  decode(lpad(to_hex(i), 8, '0'), 'hex')
FROM generate_series(1, 100) AS i
CROSS JOIN LATERAL (
  SELECT CASE
    WHEN i <= 2 THEN 1
    WHEN i <= 6 THEN 2
    WHEN i <= 14 THEN 3
    WHEN i <= 30 THEN 4
    ELSE 5
  END AS lvl
) AS depth
CROSS JOIN LATERAL (
  SELECT
    -- Milliseconds cycle: 0, 7, 123, 456, 999
    (ARRAY[0, 7, 123, 456, 999])[1 + ((i - 1) % 5)] AS ms,
    (ARRAY[0, 7, 123, 456, 999])[1 + (i % 5)] AS ms_alt
) AS ms
CROSS JOIN LATERAL (
  SELECT
    timestamp '2026-01-01 12:00:00'
      + ((i - 1) * interval '1 day')
      + (ms.ms || ' milliseconds')::interval AS col_timestamp,
    -- Same wall clock as json UTC base, but offset is NOT compensated:
    -- 12:00+03 ≠ 12:00+00 as absolute time → sort differs from naive timestamp.
    -- PostgREST still returns UTC; hour jumps reveal the source zone.
    (
      to_char(
        timestamp '2026-01-01 12:00:00'
          + ((i - 1) * interval '1 day 1 hour')
          + (ms.ms || ' milliseconds')::interval,
        'YYYY-MM-DD HH24:MI:SS.MS'
      )
      || CASE (i % 8)
           WHEN 0 THEN '+00:00'
           WHEN 1 THEN '+03:00'
           WHEN 2 THEN '-05:00'
           WHEN 3 THEN '+09:00'
           WHEN 4 THEN '+05:30'
           WHEN 5 THEN '-08:00'
           WHEN 6 THEN '+01:00'
           ELSE '-03:30'
         END
    )::timestamptz AS col_timestamptz,
    -- UTC progression for jsondata.datetime string variants (zone is notation only).
    timestamptz '2026-01-01 12:00:00+00'
      + ((i - 1) * interval '1 day 1 hour')
      + (ms.ms || ' milliseconds')::interval AS base_instant
) AS t
CROSS JOIN LATERAL (
  SELECT
    t.col_timestamp,
    t.col_timestamptz,
    CASE (i % 8)
      -- UTC Z, no fractional seconds
      WHEN 0 THEN
        to_char(t.base_instant AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS') || 'Z'
      -- UTC Z with milliseconds
      WHEN 1 THEN
        to_char(t.base_instant AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS') || 'Z'
      -- Same absolute instant written as +03:00
      WHEN 2 THEN
        to_char(
          (t.base_instant AT TIME ZONE 'UTC') + interval '3 hours',
          'YYYY-MM-DD"T"HH24:MI:SS.MS'
        ) || '+03:00'
      -- -05:00, no ms
      WHEN 3 THEN
        to_char(
          (t.base_instant AT TIME ZONE 'UTC') - interval '5 hours',
          'YYYY-MM-DD"T"HH24:MI:SS'
        ) || '-05:00'
      -- +09:00 with space separator (not T)
      WHEN 4 THEN
        to_char(
          (t.base_instant AT TIME ZONE 'UTC') + interval '9 hours',
          'YYYY-MM-DD HH24:MI:SS.MS'
        ) || '+09:00'
      -- Naive (no zone) — UI treats as UTC; PG ::timestamptz uses session TZ
      WHEN 5 THEN
        to_char(t.base_instant AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS')
      -- Naive with ms
      WHEN 6 THEN
        to_char(t.base_instant AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS')
      -- Offset without colon
      ELSE
        to_char(t.base_instant AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS') || '+0000'
    END AS json_datetime
) AS dt;

-- 900 additional rows with deterministic pseudo-random and repeated values.
-- IDs remain unique, while most searchable/typed values intentionally repeat.
  id, parent, jsondata, text, varchar, char,
  smallint, integer, bigint, numeric, real, double_precision,
  boolean, date, time, timestamp, timestamptz, interval, uuid,
  json, jsonb, money, bytea
)
SELECT
  'DEMO-' || lpad(i::text, 4, '0'),
  'DEMO-' || lpad((15 + ((i - 101) % 16))::text, 3, '0'),
  jsonb_build_object(
    'text', (ARRAY['Alpha', 'Bravo', 'Charlie', 'Delta', 'Echo'])[1 + (i % 5)],
    'number', ((i * 17) % 100)::numeric / 4,
    'boolean', i % 2 = 0,
    'status', (ARRAY['Active', 'Pending', 'Archived', 'Draft'])[1 + (i % 4)],
    'category', (ARRAY['A', 'B', 'C', 'D', 'E', 'F'])[1 + (i % 6)],
    'token', substr(md5('demo-' || i::text), 1, 8)
  ),
  (ARRAY['Alpha item', 'Bravo item', 'Charlie item', 'Delta item', 'Echo item'])[1 + (i % 5)],
  (ARRAY['C-001', 'C-002', 'C-003', 'C-004', 'C-005'])[1 + (i % 5)],
  chr(65 + (i % 5)),
  ((i * 13) % 200 - 100)::smallint,
  (i * 17) % 1000,
  ((i * 1000003) % 100000000)::bigint,
  (((i * 37) % 10000) / 100.0)::numeric(14, 4),
  (((i * 11) % 100) / 4.0)::real,
  (((i * 19) % 1000) / 3.0)::double precision,
  i % 2 = 0,
  date '2024-01-01' + ((i * 7) % 90),
  time '06:00' + ((i * 37) % 720)::int * interval '1 minute',
  timestamp '2024-01-01 08:00:00' + ((i * 11) % 120) * interval '1 hour',
  timestamptz '2024-01-01 08:00:00+00' + ((i * 13) % 120) * interval '1 hour',
  make_interval(days => (i * 3) % 30, mins => (i * 7) % 60),
  (
    substr(md5('uuid-' || i::text), 1, 8) || '-' ||
    substr(md5('uuid-' || i::text), 9, 4) || '-' ||
    '4' || substr(md5('uuid-' || i::text), 14, 3) || '-' ||
    'a' || substr(md5('uuid-' || i::text), 18, 3) || '-' ||
    substr(md5('uuid-' || i::text), 21, 12)
  )::uuid,
  json_build_object(
    'group', (i % 12),
    'label', (ARRAY['North', 'South', 'East', 'West'])[1 + (i % 4)]
  ),
  jsonb_build_object(
    'region', (ARRAY['EU', 'US', 'APAC'])[1 + (i % 3)],
    'rank', (i * 23) % 50,
    'flags', CASE
      WHEN i % 3 = 0 THEN jsonb_build_array('one')
      WHEN i % 3 = 1 THEN jsonb_build_array('two', 'demo')
      ELSE jsonb_build_array('three')
    END
  ),
  (((i * 29) % 10000) / 100.0)::money,
  decode(lpad(to_hex(i % 32), 8, '0'), 'hex')
FROM generate_series(101, 1000) AS i;

-- Fill global search (search) for the freshly seeded demo rows.
SELECT * FROM postgresto.search_refresh('postgresto', 'demo');

NOTIFY pgrst, 'reload schema';



